package com.markettwits.sportsouce.club.dashboard.presentation.store

import com.arkivanov.mvikotlin.core.store.Reducer
import com.markettwits.sportsouce.club.dashboard.presentation.store.ClubDashboardStore.Message
import com.markettwits.sportsouce.club.dashboard.presentation.store.ClubDashboardStore.State

internal object ClubDashboardReducer : Reducer<State, Message> {
    override fun State.reduce(msg: Message): State {
        return when (msg) {
            is Message.Failed -> copy(isLoading = false, error = msg.error)
            is Message.Loading -> copy(isLoading = true, error = null)
            is Message.UpdateBottomSheetData -> copy(bottomSheetData = msg.data, isLoading = false, error = null)
        }
    }
}